 "content": "def transform(grid):
    """Return a 3x3 block in the color of the largest monochrome component."""
    h, w = len(grid), len(grid[0])
    seen = set()
    best_size, best_color = -1, 0
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            size = 0
            while stack:
                y, x = stack.pop()
                size += 1
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
